-- 取回 meas
WITH `base` AS (SELECT `ds_orders`.`Row ID` AS `f_row_id`, `ds_orders`.`Order ID` AS `f_order_id`, `ds_orders`.`Order Date` AS `f_order_date`, `ds_orders`.`Ship Date` AS `f_ship_date`, `ds_orders`.`Ship Mode` AS `f_ship_mode`, `ds_orders`.`Customer ID` AS `f_customer_id`, `ds_orders`.`Customer Name` AS `f_customer_name`, `ds_orders`.`Segment` AS `f_segment`, `ds_orders`.`Country/Region` AS `f_country_region`, `ds_orders`.`City` AS `f_city`, `ds_orders`.`State/Province` AS `f_state_province`, `ds_orders`.`Postal Code` AS `f_postal_code`, `ds_orders`.`Region` AS `f_region`, `ds_orders`.`Product ID` AS `f_product_id`, `ds_orders`.`Category` AS `f_category`, `ds_orders`.`Sub-Category` AS `f_sub_category`, `ds_orders`.`Product Name` AS `f_product_name`, `ds_orders`.`Sales` AS `f_sales`, `ds_orders`.`Quantity` AS `f_quantity`, `ds_orders`.`Discount` AS `f_discount`, `ds_orders`.`Profit` AS `f_profit` FROM `sales`.`ds_orders` AS `ds_orders`), `src` AS (SELECT * FROM `base` WHERE (`f_country_region` IN ('United States'))), `lod` AS (SELECT `f_region` AS `__d0`, SUM(`f_sales`) AS `__v` FROM `src` GROUP BY `f_region`), `ctx_ext` AS (SELECT `r`.*, `l0`.`__v` AS `__lod_0` FROM `src` AS `r` LEFT JOIN `lod` AS `l0` ON `r`.`f_region` <=> `l0`.`__d0`), `dimf` AS (SELECT * FROM `ctx_ext` WHERE (`f_segment` IN ('Consumer', 'Corporate'))), `agg` AS (SELECT `f_region` AS `__k0`, CAST(YEAR(`f_order_date`) AS BIGINT) AS `__k1`, SUM(`f_sales`) AS `__a0` FROM `dimf` GROUP BY `f_region`, CAST(YEAR(`f_order_date`) AS BIGINT)), `combos` AS (SELECT DISTINCT `f_region` AS `__g0`, CAST(YEAR(`f_order_date`) AS BIGINT) AS `__g1`, `__lod_0` FROM `dimf`), `combo_agg` AS (SELECT `__g0` AS `__k0`, `__g1` AS `__k1`, SUM((`__lod_0`)) AS `__a1` FROM `combos` GROUP BY `__g0`, `__g1`), `agg_1` AS (SELECT `b`.*, `c0`.`__a1` FROM `agg` AS `b` LEFT JOIN `combo_agg` AS `c0` ON `b`.`__k0` <=> `c0`.`__k0` AND `b`.`__k1` <=> `c0`.`__k1`), `meas` AS (SELECT *, ((CAST(`__a0` AS DOUBLE) / NULLIF(CAST(`__a1` AS DOUBLE), 0))) AS `__m0`, `__a0` AS `__m1` FROM `agg_1`) SELECT * FROM `meas`
